"""Language-detector selection and label-space alignment.

The detector (fastText) and the translator (Seamless M4T v2) speak different
label spaces. `lid.176` emits ~176 two-letter labels. GlotLID-v3 emits 2,000+
`<iso639-3>_<Script>` labels (for example `uzn_Cyrl`). Whatever the detector
emits must end in one of three explicit outcomes, so a confident detection of
a language the translator cannot handle can never silently pick a wrong
fallback:

* ``supported``: the normalised code is a language the translator accepts;
* ``relative``: the language has no translator support but maps to a mutually
  intelligible supported relative (``UNSUPPORTED_TRANSLATION_FALLBACKS``);
* ``declined``: neither; the caller keeps the original text.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

LID176 = "lid176"
GLOTLID = "glotlid"
DETECTORS = (LID176, GLOTLID)

GLOTLID_MODEL_URL = "https://huggingface.co/cis-lmu/glotlid/resolve/main/model_v3.bin"
GLOTLID_DEFAULT_PATH = "glotlid_v3.bin"

# Candidates requested from a script-suffixed model before merging, so that
# folding `srp_Cyrl` and `srp_Latn` into one language cannot starve top-k.
_GLOTLID_OVERFETCH = 3


def detector_settings(name: str, env: dict) -> tuple[str, str]:
    """Return ``(model_path, model_url)`` for a detector name; unknown names are an error."""
    if name == LID176:
        return env.get("FASTTEXT_MODEL_PATH", "lid.176.bin"), "https://dl.fbaipublicfiles.com/fasttext/supervised-models/lid.176.bin"
    if name == GLOTLID:
        return env.get("GLOTLID_MODEL_PATH", GLOTLID_DEFAULT_PATH), GLOTLID_MODEL_URL
    raise ValueError(f"Unknown LANGUAGE_DETECTOR {name!r}; expected one of {', '.join(DETECTORS)}")


def base_language(label: str) -> str:
    """Strip the fastText prefix and any script suffix: ``__label__uzn_Cyrl`` -> ``uzn``."""
    return label.replace("__label__", "").split("_", 1)[0]


@dataclass(frozen=True)
class Resolution:
    kind: Literal["supported", "relative", "declined"]
    language: str


def resolve_label(label: str) -> Resolution:
    """Classify any detector label. Total: every string yields exactly one outcome."""
    from src.endpoints.translation import (
        SUPPORTED_TRANSLATION_LANGUAGES,
        UNSUPPORTED_TRANSLATION_FALLBACKS,
        _normalize_translation_language,
    )

    cleaned = label.strip().lower().replace("__label__", "")
    base = cleaned.split("_", 1)[0].split("-", 1)[0]
    normalised = _normalize_translation_language(label.replace("__label__", "").split("_", 1)[0]) or ""
    if base in UNSUPPORTED_TRANSLATION_FALLBACKS:
        return Resolution("relative", normalised)
    if normalised in SUPPORTED_TRANSLATION_LANGUAGES:
        return Resolution("supported", normalised)
    return Resolution("declined", normalised or base)


class ScriptMergingDetector:
    """Presents a script-suffixed fastText model through the plain `predict` contract.

    Probabilities of labels that differ only by script are summed, so one
    language is not split across several candidates. Output labels keep the
    ``__label__`` prefix, so existing callers need no change.
    """

    def __init__(self, model):
        self._model = model

    def predict(self, text: str, k: int = 1):
        labels, probs = self._model.predict(text, k=max(k, 1) * _GLOTLID_OVERFETCH)
        merged: dict[str, float] = {}
        for label, prob in zip(labels, probs):
            language = base_language(label)
            merged[language] = merged.get(language, 0.0) + float(prob)
        ranked = sorted(merged.items(), key=lambda item: item[1], reverse=True)[: max(k, 1)]
        return tuple(f"__label__{language}" for language, _ in ranked), tuple(prob for _, prob in ranked)

    def get_labels(self):
        return self._model.get_labels()

"""Detector selection, GlotLID label normalisation, and label-space alignment.

The property worth pinning is that every label a detector can emit resolves to
exactly one explicit outcome: supported, a supported relative, or declined. A
confident detection of a language the translator cannot handle must never
silently choose a different language.
"""

import os
from types import SimpleNamespace

import pytest

from src.endpoints.translation import (
    SUPPORTED_TRANSLATION_LANGUAGES,
    TRANSLATION_LANGUAGE_ALIASES,
    UNSUPPORTED_TRANSLATION_FALLBACKS,
    UNTRANSLATABLE_LANGUAGES,
    _normalize_translation_language,
)
from src.helpers import language_detector as ld

SCRIPTS = ("Latn", "Cyrl", "Arab", "Hant", "Deva")

# Labels that GlotLID emits for the audited misclassifications (issue #33).
AUDITED = ["kin_Latn", "uzn_Cyrl", "uzn_Latn", "hrv_Latn", "srp_Cyrl", "srp_Latn", "bos_Latn", "som_Latn", "fra_Latn", "scn_Latn"]


def label_space():
    """Every language code the service already names, in every GlotLID label shape."""
    codes = (
        set(SUPPORTED_TRANSLATION_LANGUAGES)
        | set(TRANSLATION_LANGUAGE_ALIASES)
        | set(UNSUPPORTED_TRANSLATION_FALLBACKS)
        | set(UNTRANSLATABLE_LANGUAGES)
        | {"xyz", "qqq", "zzz"}  # codes the translator knows nothing about
    )
    codes = {code.split("-", 1)[0] for code in codes}
    labels = {f"__label__{code}_{script}" for code in codes for script in SCRIPTS}
    labels |= {f"__label__{code}" for code in codes}
    labels |= {f"__label__{label}" for label in AUDITED}
    return sorted(labels)


@pytest.mark.parametrize("label", label_space())
def test_every_label_resolves_to_one_explicit_outcome(label):
    resolution = ld.resolve_label(label)

    assert resolution.kind in {"supported", "relative", "declined"}
    if resolution.kind in {"supported", "relative"}:
        assert resolution.language in SUPPORTED_TRANSLATION_LANGUAGES
    else:
        # Declined means the translator is never asked to guess another language.
        assert resolution.language not in SUPPORTED_TRANSLATION_LANGUAGES


def test_audited_labels_resolve_as_the_issue_requires():
    kinds = {label: ld.resolve_label(label).kind for label in AUDITED}

    assert kinds["kin_Latn"] == "declined"      # Kinyarwanda: kept, never mistranslated
    assert kinds["scn_Latn"] == "declined"      # Sicilian: explicit, not a silent fallback
    assert kinds["fra_Latn"] == "supported"
    assert kinds["uzn_Cyrl"] == "supported" and ld.resolve_label("uzn_Cyrl").language == "uzn"
    assert ld.resolve_label("cnr_Latn") == ld.Resolution("relative", "sr")


def test_resolution_agrees_with_the_translation_endpoint_normaliser():
    for label in label_space():
        resolution = ld.resolve_label(label)
        assert resolution.language == (_normalize_translation_language(ld.base_language(label)) or ld.base_language(label).lower())


def test_base_language_strips_prefix_and_script():
    assert ld.base_language("__label__uzn_Cyrl") == "uzn"
    assert ld.base_language("__label__en") == "en"


def test_detector_settings_select_model_and_reject_unknown_names():
    assert ld.detector_settings("lid176", {}) == ("lid.176.bin", "https://dl.fbaipublicfiles.com/fasttext/supervised-models/lid.176.bin")
    assert ld.detector_settings("lid176", {"FASTTEXT_MODEL_PATH": "/m/x.bin"})[0] == "/m/x.bin"
    assert ld.detector_settings("glotlid", {}) == ("glotlid_v3.bin", ld.GLOTLID_MODEL_URL)
    assert ld.detector_settings("glotlid", {"GLOTLID_MODEL_PATH": "/m/g.bin"})[0] == "/m/g.bin"
